#!/usr/bin/env python3
"""Recreate fixture_tools/ byte-for-byte.

Contents are stored base64-encoded and written in BINARY mode on purpose, so a
text-mode round trip cannot silently rewrite line endings and invalidate the
committed sample report hashes.

EMPTY_DIRS is not decoration. Four case directories are deliberately empty --
they exist only to give a case a working directory in which the tool under test
finds no input. os.walk yields no files for them, so an earlier version of this
generator dropped them and the regenerated tree produced a DIFFERENT report
hash. Empty directories are part of the fixture.

Regenerating and re-running reproduces the committed sample reports
byte-for-byte; captured_output.txt shows that round trip.

    python3 make_fixtures.py [dest]
"""
import base64
import os
import sys

EMPTY_DIRS = [
 "fixture_tools/cases/linecount_misuse",
 "fixture_tools/cases/sleeper_findings",
 "fixture_tools/cases/sleeper_misuse",
 "fixture_tools/cases/sleeper_ok"
]

FILES = {
 "fixture_tools/cases/linecount_empty/blank.txt": "ICAgCgogIAo=",
 "fixture_tools/cases/linecount_ok/notes.txt": "Zmlyc3QgbGluZSBoYXMgd29yZHMKc2Vjb25kIGxpbmUgdG9vCg==",
 "fixture_tools/cases/validate_findings/bad.json": "eyJuYW1lIjogIiIsICJhZ2UiOiAtMX0K",
 "fixture_tools/cases/validate_misuse/not_json.txt": "dGhpcyBpcyBub3QganNvbiBhdCBhbGwge3t7Cg==",
 "fixture_tools/cases/validate_ok/good.json": "eyJuYW1lIjogIkFkYSBMb3ZlbGFjZSIsICJhZ2UiOiAzNn0K",
 "fixture_tools/linecount.py": "",
 "fixture_tools/sleeper.py": "",
 "fixture_tools/validator.py": ""
}


def main():
    dest = sys.argv[1] if len(sys.argv) > 1 else "."
    for rel in sorted(EMPTY_DIRS):
        os.makedirs(os.path.join(dest, *rel.split("/")), exist_ok=True)
    for rel in sorted(FILES):
        path = os.path.join(dest, *rel.split("/"))
        parent = os.path.dirname(path)
        if parent:
            os.makedirs(parent, exist_ok=True)
        with open(path, "wb") as fh:
            fh.write(base64.b64decode(FILES[rel]))
    print("wrote %d files and %d empty dirs to %s"
          % (len(FILES), len(EMPTY_DIRS), dest))
    return 0


if __name__ == "__main__":
    sys.exit(main())
